function operational_calendar_save_capacity(array$record):array{if(!in_array((int)$record['company_id'],permitted_company_ids(),true))throw new RuntimeException('Capacity company is outside the active user scope.');$hours=max(1,min(80,(float)$record['weekly_capacity_hours']));$record['weekly_capacity_hours']=$hours;$record['daily_capacity_hours']=max(1,min(24,(float)$record['daily_capacity_hours']));$record['max_active_items']=max(1,min(500,(int)$record['max_active_items']));return operational_calendar_save_row('enterprise_capacity_profiles','enterprise_capacity_profiles','operational_calendar_demo_capacity_profiles',$record,['user_id','company_id','weekly_capacity_hours','daily_capacity_hours','max_active_items','utilization_warning_pct','utilization_critical_pct','timezone','status','effective_from','effective_to','evidence_note']);}
function operational_calendar_save_delegation(array$record):array{if((int)$record['source_user_id']===(int)$record['delegate_user_id'])throw new RuntimeException('A user cannot delegate work to the same account.');if(!entity_system_find_entity((int)$record['entity_id']))throw new RuntimeException('Delegation entity is outside the active company scope.');$users=data_admin_visible_users();$source=array_find_by_id($users,(int)$record['source_user_id']);$delegate=array_find_by_id($users,(int)$record['delegate_user_id']);if(!$source||!$delegate||($source['status']??'')!=='active'||($delegate['status']??'')!=='active')throw new RuntimeException('Delegation requires two active visible internal users.');if(strtotime((string)$record['ends_at'])<=strtotime((string)$record['starts_at']))throw new RuntimeException('Delegation end must be after its start.');$record['permission_keys_json']=json_encode(array_values(array_filter(array_map('strval',(array)($record['permission_keys_json']??[])))));return operational_calendar_save_row('enterprise_delegations','enterprise_delegations','operational_calendar_demo_delegations',$record,['delegation_number','source_user_id','delegate_user_id','entity_id','permission_keys_json','starts_at','ends_at','status','reason','created_by','reviewed_by','approved_by','activated_at','revoked_at']);}
