function operational_calendar_work_event_source_key(int$workItemId):string{return hash('sha256','work_item|'.$workItemId);}
function operational_calendar_sync_work_items():int{$created=0;$existing=[];foreach(operational_calendar_raw_rows('enterprise_calendar_events','enterprise_calendar_events','operational_calendar_demo_events')as$event)$existing[(string)$event['source_key']]=$event;foreach(work_management_items()as$item){if(in_array((string)$item['status'],['completed','cancelled'],true)||empty($item['due_at']))continue;$key=operational_calendar_work_event_source_key((int)$item['id']);$record=$existing[$key]??[];$record=array_replace($record,['event_number'=>$record['event_number']??'CAL-WORK-'.$item['id'],'source_key'=>$key,'source_module'=>'work_management','source_type'=>'work_item','source_id'=>(int)$item['id'],'entity_id'=>(int)$item['entity_id'],'company_id'=>(int)$item['company_id'],'owner_user_id'=>(int)($item['assigned_user_id']??$item['created_by']),'title'=>(string)$item['work_number'].' · '.$item['title'],'description'=>(string)$item['description'],'event_type'=>'work_due','visibility'=>'team','participant_user_ids_json'=>array_values(array_filter([(int)($item['assigned_user_id']??0),(int)($item['reviewer_id']??0),(int)($item['approver_id']??0)])),'starts_at'=>date('Y-m-d H:i:s',strtotime((string)$item['due_at'])-1800),'ends_at'=>(string)$item['due_at'],'all_day'=>0,'status'=>'scheduled','location'=>'','required_permission'=>(string)$item['required_permission'],'created_by'=>(int)$item['created_by']]);operational_calendar_save_event($record);if(!isset($existing[$key]))$created++;}return$created;}
function operational_calendar_capacity_snapshot():array{$profiles=operational_calendar_capacity_profiles();$items=work_management_items();$rows=[];foreach($profiles as$profile){$uid=(int)$profile['user_id'];$active=array_values(array_filter($items,static fn(array$item):bool=>(int)($item['assigned_user_id']??0)===$uid&&!in_array((string)$item['status'],['completed','cancelled'],true)));$estimatedHours=array_sum(array_map(static function(array$item):float{return match((string)$item['priority']){'critical'=>4.0,'high'=>3.0,'medium'=>2.0,default=>1.0};},$active));$weekly=max(1,(float)$profile['weekly_capacity_hours']);$util=round(($estimatedHours/$weekly)*100,1);$rows[]=['profile'=>$profile,'user_id'=>$uid,'active_items'=>count($active),'estimated_hours'=>$estimatedHours,'utilization_pct'=>$util,'state'=>$util>=(float)$profile['utilization_critical_pct']?'critical':($util>=(float)$profile['utilization_warning_pct']?'warning':'available')];}usort($rows,static fn(array$a,array$b):int=>$b['utilization_pct']<=>$a['utilization_pct']);return$rows;}
function operational_calendar_active_delegation(int$sourceUserId,string$permission,int$entityId):?array{$now=time();foreach(operational_calendar_delegations()as$row){if((int)$row['source_user_id']!==$sourceUserId||(int)$row['entity_id']!==$entityId||($row['status']??'')!=='active')continue;if(strtotime((string)$row['starts_at'])>$now||strtotime((string)$row['ends_at'])<$now)continue;if(in_array($permission,array_map('strval',operational_calendar_json_ids([])),true)){}$permissions=json_decode((string)$row['permission_keys_json'],true);if(is_array($permissions)&&in_array($permission,$permissions,true))return$row;}return null;}
function operational_calendar_generate_digest(string$type='daily'):array{$user=current_user()??[];$uid=(int)($user['id']??0);$start=$type==='weekly'?date('Y-m-d 00:00:00',strtotime('monday this week')):date('Y-m-d 00:00:00');$end=$type==='weekly'?date('Y-m-d 23:59:59',strtotime('sunday this week')):date('Y-m-d 23:59:59');$events=operational_calendar_events($start,$end);$items=work_management_my_items($user);$notifications=array_values(array_filter(operational_calendar_notifications($uid),static fn(array$n):bool=>empty($n['read_at'])));$critical=count(array_filter($items,static fn(array$item):bool=>$item['priority']==='critical'&&!in_array($item['status'],['completed','cancelled'],true)));$overdue=count(array_filter($items,'work_management_item_overdue'));$summary=status_label($type).' operating digest: '.count($items).' assigned work items, '.$critical.' critical, '.$overdue.' overdue, '.count($events).' calendar events, and '.count($notifications).' unread notifications.';$key=hash('sha256',$uid.'|'.$type.'|'.$start.'|'.$end);return operational_calendar_save_digest(['id'=>null,'user_id'=>$uid,'entity_id'=>null,'digest_type'=>$type,'period_start'=>$start,'period_end'=>$end,'status'=>'generated','item_count'=>count($items),'event_count'=>count($events),'notification_count'=>count($notifications),'summary_text'=>$summary,'idempotency_key'=>$key,'generated_at'=>date('Y-m-d H:i:s'),'delivered_at'=>null]);}
