function operational_calendar_ics_escape(string$value):string{return str_replace(["\\",",",";","\r","\n"],["\\\\","\\,","\\;",'',"\\n"],$value);}
function operational_calendar_ics(array$events):string{$lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Gruber Procurement Intelligence//Operational Calendar//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH'];foreach($events as$event){$lines[]='BEGIN:VEVENT';$lines[]='UID:'.operational_calendar_ics_escape((string)$event['event_number']).'@gruber.local';$lines[]='DTSTAMP:'.gmdate('Ymd\THis\Z');$lines[]='DTSTART:'.gmdate('Ymd\THis\Z',strtotime((string)$event['starts_at']));$lines[]='DTEND:'.gmdate('Ymd\THis\Z',strtotime((string)$event['ends_at']));$lines[]='SUMMARY:'.operational_calendar_ics_escape((string)$event['title']);$lines[]='DESCRIPTION:'.operational_calendar_ics_escape((string)$event['description']);if(!empty($event['location']))$lines[]='LOCATION:'.operational_calendar_ics_escape((string)$event['location']);$lines[]='STATUS:'.strtoupper(($event['status']??'scheduled')==='cancelled'?'CANCELLED':'CONFIRMED');$lines[]='END:VEVENT';}$lines[]='END:VCALENDAR';return implode("\r\n",$lines)."\r\n";}
