function operational_calendar_export_csv():never{require_permission('operational_calendar.export');header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="operational-calendar-'.date('Ymd').'.csv"');$o=fopen('php://output','wb');fputcsv($o,['Event','Title','Type','Company','Owner','Starts','Ends','Status']);foreach(operational_calendar_events()as$event)fputcsv($o,[spreadsheet_safe($event['event_number']),spreadsheet_safe($event['title']),spreadsheet_safe($event['event_type']),spreadsheet_safe(data_company_name((int)$event['company_id'])),spreadsheet_safe(data_user_name((int)$event['owner_user_id'])),spreadsheet_safe($event['starts_at']),spreadsheet_safe($event['ends_at']),spreadsheet_safe($event['status'])]);fclose($o);exit;}
function operational_calendar_metrics():array{$events=operational_calendar_events();$today=date('Y-m-d');$upcoming=array_values(array_filter($events,static fn(array$e):bool=>strtotime((string)$e['starts_at'])>=time()&&($e['status']??'')!=='cancelled'));$todayEvents=array_values(array_filter($events,static fn(array$e):bool=>str_starts_with((string)$e['starts_at'],$today)));$notifications=operational_calendar_notifications();$capacity=operational_calendar_capacity_snapshot();return['events'=>count($events),'today'=>count($todayEvents),'upcoming'=>count($upcoming),'unread_notifications'=>count(array_filter($notifications,static fn(array$n):bool=>empty($n['read_at']))),'over_capacity'=>count(array_filter($capacity,static fn(array$r):bool=>$r['state']==='critical')),'active_delegations'=>count(array_filter(operational_calendar_delegations(),static fn(array$d):bool=>$d['status']==='active'&&strtotime((string)$d['starts_at'])<=time()&&strtotime((string)$d['ends_at'])>=time())),'subscriptions'=>count(array_filter(operational_calendar_subscriptions(),static fn(array$s):bool=>$s['status']==='active')),'digests'=>count(operational_calendar_digest_runs())];}

