function operational_calendar_agent_extend_workspace(array$workspace):array{$metrics=operational_calendar_metrics();$events=array_values(array_filter(operational_calendar_events(),static fn(array$e):bool=>strtotime((string)$e['ends_at'])>=time()));usort($events,static fn(array$a,array$b):int=>strcmp((string)$a['starts_at'],(string)$b['starts_at']));$capacity=operational_calendar_capacity_snapshot();$eventRows=[];foreach(array_slice($events,0,6)as$event)$eventRows[]='<li><strong>'.h($event['title']).'</strong> · '.h(date_us($event['starts_at'],true)).' · '.h(data_company_name((int)$event['company_id'])).'</li>';$capacityRows=[];foreach(array_slice($capacity,0,5)as$row)$capacityRows[]='<li><strong>'.h(data_user_name($row['user_id'])).'</strong> · '.h(number_format((float)$row['utilization_pct'],1)).'% capacity · '.(int)$row['active_items'].' active items</li>';$prompt=['icon'=>'◷','title'=>'Operational calendar and capacity','description'=>'Review upcoming work, operating cadences, workload capacity, delegation, and notification pressure.','prompt'=>'Give me today’s operational calendar and workload capacity briefing.','keywords'=>['calendar','schedule','capacity','workload','delegation','digest','notification','today'],'response_title'=>'Operational Calendar Agent','response_html'=>'<p><strong>'.$metrics['today'].' events today · '.$metrics['unread_notifications'].' unread notifications · '.$metrics['over_capacity'].' users over capacity.</strong></p><ul>'.implode('',$eventRows).'</ul><h4>Capacity</h4><ul>'.implode('',$capacityRows).'</ul><p>Human review is required before reassignment, delegation, escalation, or schedule changes.</p><a class="agent-inline-link" href="'.h(app_url('operational-calendar.php')).'">Open Operational Calendar →</a>','evidence'=>[$metrics['events'].' visible events',$metrics['unread_notifications'].' unread notifications',$metrics['active_delegations'].' active delegations',$metrics['over_capacity'].' critical capacity profiles'],'actions'=>[['type'=>'link','icon'=>'◷','label'=>'Open operational calendar','description'=>'Review events, capacity and delegation','href'=>app_url('operational-calendar.php')],['type'=>'prompt','icon'=>'☀','label'=>'Morning summary','description'=>'Prioritize today’s work and meetings','prompt'=>'Create a morning operating summary from today’s work queue, calendar, notifications, and capacity.']],'confidence'=>'High','generated_at'=>date('Y-m-d H:i:s'),'human_review'=>'Required before any operational change','missing_data'=>[]];array_unshift($workspace['prompts'],$prompt);$workspace['metrics']['calendar_events']=$metrics['upcoming'];$workspace['metrics']['unread_notifications']=$metrics['unread_notifications'];$workspace['metrics']['over_capacity']=$metrics['over_capacity'];return$workspace;}

function operational_calendar_render_styles():void{echo '<style>.calendar-metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin-bottom:18px}.calendar-metrics article,.capacity-card,.calendar-event{background:#fff;border:1px solid #dfe5ec;border-radius:16px;padding:16px}.calendar-metrics span,.capacity-card small,.calendar-event small{display:block;color:#64748b;font-size:12px}.calendar-metrics strong{display:block;font-size:26px;margin-top:4px}.calendar-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(300px,.8fr);gap:18px}.calendar-event{display:grid;grid-template-columns:92px 1fr auto;gap:14px;align-items:start;margin-bottom:10px}.calendar-time{font-weight:800}.calendar-event h3{margin:0 0 5px}.calendar-event p{margin:0;color:#475569}.capacity-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.capacity-meter{height:9px;border-radius:999px;background:#e5e7eb;overflow:hidden;margin:12px 0}.capacity-meter i{display:block;height:100%;background:currentColor}.capacity-card.available{color:#166534}.capacity-card.warning{color:#a16207}.capacity-card.critical{color:#b91c1c}.calendar-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.calendar-tabs a{padding:9px 13px;border:1px solid #dbe2ea;border-radius:999px;text-decoration:none}.calendar-tabs a.active{background:#111827;color:#fff}.notification-row-ops{display:grid;grid-template-columns:10px 1fr auto;gap:12px;padding:14px 0;border-bottom:1px solid #edf0f3}.notification-row-ops i{width:8px;height:8px;border-radius:999px;margin-top:7px;background:#64748b}.notification-row-ops.critical i{background:#dc2626}.notification-row-ops.warning i{background:#d97706}.calendar-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.calendar-form-grid .span-2{grid-column:1/-1}@media(max-width:980px){.calendar-metrics{grid-template-columns:repeat(3,1fr)}.calendar-grid{grid-template-columns:1fr}.capacity-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:640px){.calendar-metrics,.capacity-grid,.calendar-form-grid{grid-template-columns:1fr}.calendar-event{grid-template-columns:1fr}.calendar-form-grid .span-2{grid-column:auto}}</style>';}
function operational_calendar_render_event(array$event):void{echo '<article class="calendar-event"><div class="calendar-time">'.h(date('g:i A',strtotime((string)$event['starts_at']))).'<small>'.h(date('M j',strtotime((string)$event['starts_at']))).'</small></div><div><h3>'.h($event['title']).'</h3><p>'.h($event['description']).'</p><small>'.h(data_company_name((int)$event['company_id'])).' · '.h(status_label($event['event_type'])).' · '.h(data_user_name((int)$event['owner_user_id'])).'</small></div><div>'.badge($event['status']).'</div></article>';}
